style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
body {
    background-image: url("https://i.imgur.com/IxEus7k.jpeg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
  }

  /* Estilização de texto com o verde galvânico do Ultra T */
  body, p, h1, h2, h3, h4, h5, h6, span, li, a {
    color: #00FF00 !important;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
    text-shadow: 0 0 4px rgba(0, 255, 0, 0.6) !important;
  }

  /* Seleção de texto no estilo Omnitrix */
  ::selection {
    background: #00FF00 !important;
    color: #000000 !important;
  }
}
